-- Persist the bundled Urban Castle work catalog into the canonical Supabase
-- master tables. Runtime reads must use these rows rather than silently replacing
-- them from bundled JSON. Existing persisted fields win on conflict so custom
-- names/rates/metadata already entered in Supabase are preserved.

begin;

insert into public."entity_master_units" (id, workspace_id, revision, updated_at, updated_by, data)
select seed.id, ws.workspace_id, 0, now(), 'work-catalog-seed', seed.data
from public.entity_workspace_revision ws
cross join (
  values
      ('sqft', '{"id":"sqft","symbol":"sqft","name":"Square feet","family":"area"}'::jsonb),
      ('rft', '{"id":"rft","symbol":"rft","name":"Running feet","family":"length"}'::jsonb),
      ('pcs', '{"id":"pcs","symbol":"pcs","name":"Pieces","family":"count"}'::jsonb),
      ('kg', '{"id":"kg","symbol":"kg","name":"Kilograms","family":"weight"}'::jsonb),
      ('ltr', '{"id":"ltr","symbol":"ltr","name":"Litres","family":"volume"}'::jsonb),
      ('box', '{"id":"box","symbol":"box","name":"Box","family":"package"}'::jsonb),
      ('roll', '{"id":"roll","symbol":"roll","name":"Roll","family":"package"}'::jsonb),
      ('bag', '{"id":"bag","symbol":"bag","name":"Bag","family":"package"}'::jsonb),
      ('set', '{"id":"set","symbol":"set","name":"Set","family":"count"}'::jsonb),
      ('sheet', '{"id":"sheet","symbol":"sheet","name":"Sheet","family":"count"}'::jsonb),
      ('nos', '{"id":"nos","symbol":"nos","name":"Numbers","family":"count"}'::jsonb),
      ('mtr', '{"id":"mtr","symbol":"mtr","name":"Metres","family":"length"}'::jsonb),
      ('cft', '{"id":"cft","symbol":"cft","name":"Cubic feet","family":"volume"}'::jsonb),
      ('pair', '{"id":"pair","symbol":"pair","name":"Pair","family":"count"}'::jsonb),
      ('tube', '{"id":"tube","symbol":"tube","name":"Tube","family":"package"}'::jsonb),
      ('unit', '{"id":"unit","symbol":"unit","name":"Unit","family":"count"}'::jsonb),
      ('workOrder', '{"id":"workOrder","symbol":"workOrder","name":"WorkOrder","family":"other"}'::jsonb)
) as seed(id, data)
on conflict (id) do update set
  workspace_id = excluded.workspace_id,
  revision = public."entity_master_units".revision + 1,
  updated_at = excluded.updated_at,
  updated_by = excluded.updated_by,
  -- Existing persisted values win; bundled catalog only fills missing canonical fields.
  data = excluded.data || public."entity_master_units".data;

