on conflict (id) do update set
  workspace_id = excluded.workspace_id,
  revision = public."entity_master_subcategoryArticleMap".revision + 1,
  updated_at = excluded.updated_at,
  updated_by = excluded.updated_by,
  -- Existing persisted values win; bundled catalog only fills missing canonical fields.
  data = excluded.data || public."entity_master_subcategoryArticleMap".data;

-- These writes occur as a migration rather than a normal workspace operation.
-- Advance each workspace once and make that revision the fresh delta baseline,
-- forcing already-open clients to do one safe reload into the persisted catalog.
do $catalog_baseline$
declare
  v_row record;
  v_next_revision integer;
begin
  for v_row in
    select id, workspace_id, revision
      from public.entity_workspace_revision
      for update
  loop
    v_next_revision := v_row.revision + 1;

    insert into public.entity_workspace_change_batches (
      workspace_id, revision, operations, row_versions, is_baseline, created_at
    ) values (
      v_row.workspace_id, v_next_revision, '[]'::jsonb, '{}'::jsonb, true, now()
    )
    on conflict (workspace_id, revision) do update set
      operations = '[]'::jsonb,
      row_versions = '{}'::jsonb,
      is_baseline = true;

    update public.entity_workspace_revision
       set revision = v_next_revision, updated_at = now()
     where id = v_row.id;
  end loop;
end;
$catalog_baseline$;

comment on table public."entity_master_workCategories" is
  'Canonical persisted work-category master. Bundled JSON is seed/fallback material only.';
comment on table public."entity_master_workSubcategories" is
  'Canonical persisted work-subcategory master. Runtime reads must preserve Supabase rows.';

commit;
